<?php
namespace Dth\Crm\Filament\Resources;
use Dth\Crm\Models\Contact; use Dth\Crm\Filament\Navigation\CrmNavigationGroup; use Filament\Resources\Resource; use Filament\Schemas\Schema; use Filament\Schemas\Components\Section; use Filament\Forms\Components\{TextInput,Select,DatePicker}; use Filament\Tables\Table; use Filament\Tables\Columns\TextColumn; use Filament\Actions;
class BusinessContactResource extends Resource {protected static ?string $model=Contact::class;protected static string|\BackedEnum|null $navigationIcon='heroicon-o-building-office-2';protected static string|\UnitEnum|null $navigationGroup=CrmNavigationGroup::Crm;protected static ?int $navigationSort=11;public static function getNavigationLabel():string{return \Dth\Crm\Support\UiText::get('navigation.business_contacts','Business contacts',context:'navigation');}public static function getEloquentQuery():\Illuminate\Database\Eloquent\Builder{return parent::getEloquentQuery()->where('type','business');}
 public static function form(Schema $s):Schema{return $s->components([Section::make('Người liên hệ')->schema([TextInput::make('display_name')->label('Người đại diện/liên hệ')->required(),TextInput::make('email')->email()->label('Email liên hệ'),TextInput::make('phone')->tel()->label('Điện thoại'),TextInput::make('source')->label('Nguồn')])->columns(2),Section::make('Doanh nghiệp')->schema([TextInput::make('profile.company_name')->label('Tên doanh nghiệp')->required(),TextInput::make('profile.tax_code')->label('Mã số thuế'),TextInput::make('profile.company_address')->label('Địa chỉ'),TextInput::make('profile.legal_representative')->label('Đại diện pháp luật'),TextInput::make('profile.contact_position')->label('Chức vụ'),TextInput::make('profile.business_email')->email()->label('Email doanh nghiệp'),TextInput::make('profile.business_phone')->tel()->label('Điện thoại doanh nghiệp'),TextInput::make('profile.industry')->label('Ngành nghề')])->columns(2)]);}
 public static function table(Table $t):Table{return $t->columns([TextColumn::make('contact_code')->label('Mã')->searchable(),TextColumn::make('businessProfile.company_name')->label('Doanh nghiệp')->searchable(),TextColumn::make('display_name')->label('Người liên hệ')->searchable(),TextColumn::make('businessProfile.tax_code')->label('MST')->searchable(),TextColumn::make('email')->searchable(),TextColumn::make('phone')->searchable()])->recordActions([Actions\EditAction::make(),Actions\DeleteAction::make()])->bulkActions([Actions\BulkActionGroup::make([Actions\DeleteBulkAction::make()->authorizeIndividualRecords()])]);}
 public static function getPages():array{return ['index'=>BusinessContactResource\Pages\ListBusinessContacts::route('/'),'create'=>BusinessContactResource\Pages\CreateBusinessContact::route('/create'),'edit'=>BusinessContactResource\Pages\EditBusinessContact::route('/{record}/edit')];}}
